DROP VIEW "ontology"."person_view";--> statement-breakpoint
ALTER TABLE "ontology"."person" ADD COLUMN "wikidata_id" text;--> statement-breakpoint
ALTER TABLE "ontology"."person" ADD CONSTRAINT "person_wikidata_id_unique" UNIQUE("wikidata_id");--> statement-breakpoint
CREATE VIEW "ontology"."person_view" AS (select "ontology"."node_version"."id", "ontology"."node_version"."version", "ontology"."node_version"."action", "ontology"."person"."wikidata_id", "ontology"."node_version"."timestamp", "version_zero"."timestamp" as "created_at" from (select "id", max("version") as "head_version" from "ontology"."node_version" group by "ontology"."node_version"."id") "head" inner join "ontology"."node_version" on (("head"."id" = "ontology"."node_version"."id") and ("head"."head_version" = "ontology"."node_version"."version")) inner join "ontology"."node" on "head"."id" = "ontology"."node"."id" inner join "ontology"."agent_version" on (("head"."id" = "ontology"."agent_version"."id") and ("head"."head_version" = "ontology"."agent_version"."version")) inner join "ontology"."person_version" on (("head"."id" = "ontology"."person_version"."id") and ("head"."head_version" = "ontology"."person_version"."version")) inner join "ontology"."person" on "head"."id" = "ontology"."person"."id" inner join "ontology"."node_version" "version_zero" on (("head"."id" = "version_zero"."id") and ("version_zero"."version" = 0)));